@using sv_dfbf37ca17dc4ed9ab949344ff3e65f8.Models

<nav class="step-indicator" aria-label="Application progress">
    <ol class="step-list">
        @for (int i = 0; i < StepNames.Length; i++)
        {
            var step = i + 1;
            var css = step == CurrentStep ? "step active"
                    : step < CurrentStep ? "step completed"
                    : "step future";
            <li class="@css">
                @if (step < CurrentStep)
                {
                    <button class="step-button" @onclick="() => OnStepClicked.InvokeAsync(step)">
                        <span class="step-icon">&#10003;</span>
                        <span class="step-label">@StepNames[step - 1]</span>
                    </button>
                }
                else
                {
                    <span class="step-content">
                        <span class="step-number">@step</span>
                        <span class="step-label">@StepNames[step - 1]</span>
                    </span>
                }
            </li>
        }
    </ol>
</nav>

@code {
    private static readonly string[] StepNames =
    {
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    };

    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }
}

@using sv_dfbf37ca17dc4ed9ab949344ff3e65f8.Models

<div class="step-panel">
    <h2>Personal Information</h2>

    <div class="form-group">
        <label for="fullName">Full Name *</label>
        <input id="fullName" type="text" @bind="State.FullName" @bind:event="oninput" />
    </div>

    <div class="form-group">
        <label for="email">Email *</label>
        <input id="email" type="email" @bind="State.Email" @bind:event="oninput" />
    </div>

    <div class="form-group">
        <label for="phone">Phone *</label>
        <input id="phone" type="tel" @bind="State.Phone" @bind:event="oninput" />
    </div>

    <div class="form-group">
        <label for="address">Address *</label>
        <textarea id="address" @bind="State.Address" @bind:event="oninput" rows="2"></textarea>
    </div>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="error-message" role="alert">@ErrorMessage</div>
    }

    <div class="step-actions">
        <button class="btn btn-primary" @onclick="HandleNext" disabled="@IsValidating">
            @(IsValidating ? "Validating..." : "Next")
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public ApplicationFormState State { get; set; } = default!;
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public Func<string, Task<bool>>? ValidateEmail { get; set; }

    private string? ErrorMessage;
    private bool IsValidating;

    private async Task HandleNext()
    {
        ErrorMessage = null;

        if (string.IsNullOrWhiteSpace(State.FullName) ||
            string.IsNullOrWhiteSpace(State.Email) ||
            string.IsNullOrWhiteSpace(State.Phone) ||
            string.IsNullOrWhiteSpace(State.Address))
        {
            ErrorMessage = "All fields are required.";
            return;
        }

        if (ValidateEmail is not null)
        {
            IsValidating = true;
            StateHasChanged();
            var isValid = await ValidateEmail(State.Email);
            IsValidating = false;
            if (!isValid)
            {
                ErrorMessage = "The email address is not valid.";
                return;
            }
        }

        await OnNext.InvokeAsync();
    }
}

@using sv_dfbf37ca17dc4ed9ab949344ff3e65f8.Models

<div class="step-panel">
    <h2>Work History</h2>

    @for (int i = 0; i < State.WorkEntries.Count; i++)
    {
        var index = i;
        <WorkEntryForm Entry="State.WorkEntries[index]"
                       Index="index + 1"
                       CanRemove="State.WorkEntries.Count > 1"
                       OnRemove="() => RemoveEntry(index)" />
    }

    <button class="btn btn-secondary" @onclick="AddEntry">+ Add Another Position</button>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="error-message" role="alert">@ErrorMessage</div>
    }

    <div class="step-actions">
        <button class="btn btn-outline" @onclick="OnBack">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public ApplicationFormState State { get; set; } = default!;
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? ErrorMessage;

    private void AddEntry()
    {
        State.WorkEntries.Add(new WorkEntryModel());
    }

    private void RemoveEntry(int index)
    {
        if (State.WorkEntries.Count > 1)
            State.WorkEntries.RemoveAt(index);
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;
        foreach (var entry in State.WorkEntries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title))
            {
                ErrorMessage = "Each position must have at least a company name and job title.";
                return;
            }
        }
        await OnNext.InvokeAsync();
    }
}

@using sv_dfbf37ca17dc4ed9ab949344ff3e65f8.Models

<fieldset class="reference-form">
    <legend>Reference @Index</legend>

    <div class="form-group">
        <label>Name *</label>
        <input type="text" @bind="Reference.Name" @bind:event="oninput" />
    </div>

    <div class="form-group">
        <label>Relationship *</label>
        <input type="text" @bind="Reference.Relationship" @bind:event="oninput" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Email *</label>
            <input type="email" @bind="Reference.Email" @bind:event="oninput" />
        </div>
        <div class="form-group">
            <label>Phone *</label>
            <input type="tel" @bind="Reference.Phone" @bind:event="oninput" />
        </div>
    </div>

    @if (CanRemove)
    {
        <button class="btn btn-danger btn-sm" @onclick="() => OnRemove.InvokeAsync()">Remove</button>
    }
</fieldset>

@code {
    [Parameter, EditorRequired] public ReferenceModel Reference { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
}

@using sv_dfbf37ca17dc4ed9ab949344ff3e65f8.Models

<div class="step-panel">
    <h2>References</h2>
    <p class="hint">Please provide 2–3 professional references.</p>

    @for (int i = 0; i < State.References.Count; i++)
    {
        var index = i;
        <ReferenceForm Reference="State.References[index]"
                       Index="index + 1"
                       CanRemove="State.References.Count > 2"
                       OnRemove="() => RemoveReference(index)" />
    }

    @if (State.References.Count < 3)
    {
        <button class="btn btn-secondary" @onclick="AddReference">+ Add Reference</button>
    }

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="error-message" role="alert">@ErrorMessage</div>
    }

    <div class="step-actions">
        <button class="btn btn-outline" @onclick="OnBack">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public ApplicationFormState State { get; set; } = default!;
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? ErrorMessage;

    private void AddReference()
    {
        if (State.References.Count < 3)
            State.References.Add(new ReferenceModel());
    }

    private void RemoveReference(int index)
    {
        if (State.References.Count > 2)
            State.References.RemoveAt(index);
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;
        foreach (var r in State.References)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship) ||
                string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
            {
                ErrorMessage = "All reference fields are required.";
                return;
            }
        }
        await OnNext.InvokeAsync();
    }
}

@using sv_dfbf37ca17dc4ed9ab949344ff3e65f8.Models

<div class="step-panel">
    <h2>Cover Letter</h2>

    <div class="form-group">
        <textarea id="coverLetter"
                  @bind="State.CoverLetter"
                  @bind:event="oninput"
                  rows="12"
                  maxlength="@MaxLength"
                  placeholder="Write your cover letter here..."></textarea>
        <div class="char-count @(State.CoverLetter.Length > MaxLength ? "over-limit" : "")">
            @State.CoverLetter.Length / @MaxLength characters
        </div>
    </div>

    <div class="step-actions">
        <button class="btn btn-outline" @onclick="OnBack">Back</button>
        <button class="btn btn-primary" @onclick="OnNext">Next</button>
    </div>
</div>

@code {
    private const int MaxLength = 2000;

    [Parameter, EditorRequired] public ApplicationFormState State { get; set; } = default!;
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
}

@using sv_dfbf37ca17dc4ed9ab949344ff3e65f8.Models

<div class="step-panel">
    <h2>Review & Submit</h2>

    @if (IsSubmitted)
    {
        <div class="confirmation" role="status">
            <h3>&#10003; Application Submitted!</h3>
            <p>Your application ID is: <strong>@ApplicationId</strong></p>
            <p>Thank you for applying. We will be in touch soon.</p>
        </div>
    }
    else
    {
        <section class="review-section">
            <div class="review-header">
                <h3>Personal Information</h3>
                <button class="btn-link" @onclick='() => OnEditStep.InvokeAsync(1)'>Edit</button>
            </div>
            <dl>
                <dt>Name</dt><dd>@State.FullName</dd>
                <dt>Email</dt><dd>@State.Email</dd>
                <dt>Phone</dt><dd>@State.Phone</dd>
                <dt>Address</dt><dd>@State.Address</dd>
            </dl>
        </section>

        <section class="review-section">
            <div class="review-header">
                <h3>Work History</h3>
                <button class="btn-link" @onclick='() => OnEditStep.InvokeAsync(2)'>Edit</button>
            </div>
            @foreach (var entry in State.WorkEntries)
            {
                <div class="review-item">
                    <strong>@entry.Title</strong> at @entry.Company<br />
                    <span class="date-range">
                        @entry.StartDate.ToString("MMM yyyy") –
                        @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))
                    </span>
                    @if (!string.IsNullOrWhiteSpace(entry.Description))
                    {
                        <p>@entry.Description</p>
                    }
                </div>
            }
        </section>

        <section class="review-section">
            <div class="review-header">
                <h3>References</h3>
                <button class="btn-link" @onclick='() => OnEditStep.InvokeAsync(3)'>Edit</button>
            </div>
            @foreach (var r in State.References)
            {
                <div class="review-item">
                    <strong>@r.Name</strong> (@r.Relationship)<br />
                    @r.Email · @r.Phone
                </div>
            }
        </section>

        <section class="review-section">
            <div class="review-header">
                <h3>Cover Letter</h3>
                <button class="btn-link" @onclick='() => OnEditStep.InvokeAsync(4)'>Edit</button>
            </div>
            <p class="cover-letter-preview">@State.CoverLetter</p>
        </section>

        @if (!string.IsNullOrEmpty(ErrorMessage))
        {
            <div class="error-message" role="alert">@ErrorMessage</div>
        }

        <div class="step-actions">
            <button class="btn btn-outline" @onclick="OnBack">Back</button>
            <button class="btn btn-primary btn-submit" @onclick="HandleSubmit" disabled="@IsSubmitting">
                @(IsSubmitting ? "Submitting..." : "Submit Application")
            </button>
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired] public ApplicationFormState State { get; set; } = default!;
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback<int> OnEditStep { get; set; }
    [Parameter] public Func<Task<int>>? SubmitApplication { get; set; }

    private bool IsSubmitting;
    private bool IsSubmitted;
    private int ApplicationId;
    private string? ErrorMessage;

    private async Task HandleSubmit()
    {
        if (SubmitApplication is null) return;

        IsSubmitting = true;
        ErrorMessage = null;
        StateHasChanged();

        try
        {
            ApplicationId = await SubmitApplication();
            IsSubmitted = true;
        }
        catch (Exception ex)
        {
            ErrorMessage = $"Submission failed: {ex.Message}";
        }
        finally
        {
            IsSubmitting = false;
        }
    }
}

