arguments.file_text:
@page "/apply"
@using sv_dfbf37ca17dc4ed9ab949344ff3e65f8.Models
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="application-form">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="currentStep" OnStepClicked="GoToStep" />

    @switch (currentStep)
    {
        case 1:
            <PersonalInfoStep State="formState"
                              OnNext="NextStep"
                              ValidateEmail="ApplicationService.ValidateEmailAsync" />
            break;
        case 2:
            <WorkHistoryStep State="formState"
                             OnNext="NextStep"
                             OnBack="PreviousStep" />
            break;
        case 3:
            <ReferencesStep State="formState"
                            OnNext="NextStep"
                            OnBack="PreviousStep" />
            break;
        case 4:
            <CoverLetterStep State="formState"
                             OnNext="NextStep"
                             OnBack="PreviousStep" />
            break;
        case 5:
            <ReviewStep State="formState"
                        OnBack="PreviousStep"
                        OnEditStep="GoToStep"
                        SubmitApplication="SubmitAsync" />
            break;
    }
</div>

@code {
    private int currentStep = 1;
    private ApplicationFormState formState = new();

    private void NextStep() => currentStep++;
    private void PreviousStep() => currentStep--;
    private void GoToStep(int step) => currentStep = step;

    private async Task<int> SubmitAsync()
    {
        var application = formState.ToApplication();
        return await ApplicationService.SubmitApplicationAsync(application);
    }
}

.application-form {
    max-width: 720px;
    margin: 2rem auto;
    padding: 0 1rem;
}

.application-form h1 {
    text-align: center;
    margin-bottom: 1.5rem;
}

/* Step Indicator */
.step-indicator {
    margin-bottom: 2rem;
}

.step-list {
    display: flex;
    list-style: none;
    padding: 0;
    margin: 0;
    justify-content: space-between;
    gap: 0.25rem;
}

.step {
    flex: 1;
    text-align: center;
    padding: 0.75rem 0.25rem;
    border-bottom: 3px solid #e0e0e0;
    font-size: 0.85rem;
}

.step.active {
    border-bottom-color: #1976d2;
    font-weight: 600;
    color: #1976d2;
}

.step.completed {
    border-bottom-color: #4caf50;
    color: #4caf50;
}

.step.future {
    color: #9e9e9e;
}

.step-button {
    background: none;
    border: none;
    color: inherit;
    font: inherit;
    cursor: pointer;
    padding: 0;
}

.step-button:hover {
    text-decoration: underline;
}

.step-icon {
    display: block;
    font-size: 1.1rem;
}

.step-number {
    display: block;
    font-size: 1.1rem;
    font-weight: 700;
}

/* Step Panel */
.step-panel {
    background: #fff;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    padding: 1.5rem;
}

.step-panel h2 {
    margin-top: 0;
    margin-bottom: 1rem;
    font-size: 1.4rem;
}

/* Form Elements */
.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    font-weight: 500;
    margin-bottom: 0.25rem;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="tel"],
.form-group input[type="date"],
.form-group textarea {
    width: 100%;
    padding: 0.5rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 1rem;
    box-sizing: border-box;
}

.form-group textarea {
    resize: vertical;
}

.form-row {
    display: flex;
    gap: 1rem;
}

.form-row .form-group {
    flex: 1;
}

.checkbox-label {
    display: inline-flex !important;
    align-items: center;
    gap: 0.4rem;
    font-weight: normal !important;
    margin-top: 0.25rem;
}

.hint {
    color: #666;
    font-size: 0.9rem;
    margin-bottom: 1rem;
}

/* Buttons */
.step-actions {
    display: flex;
    justify-content: space-between;
    margin-top: 1.5rem;
    gap: 1rem;
}

.btn {
    padding: 0.6rem 1.4rem;
    border: none;
    border-radius: 4px;
    font-size: 1rem;
    cursor: pointer;
    transition: opacity 0.2s;
}

.btn:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-primary {
    background: #1976d2;
    color: #fff;
    margin-left: auto;
}

.btn-primary:hover:not(:disabled) {
    background: #1565c0;
}

.btn-outline {
    background: transparent;
    border: 1px solid #666;
    color: #333;
}

.btn-outline:hover {
    background: #f5f5f5;
}

.btn-secondary {
    background: #f5f5f5;
    border: 1px dashed #aaa;
    color: #333;
    padding: 0.5rem 1rem;
    margin-bottom: 1rem;
}

.btn-secondary:hover {
    background: #eee;
}

.btn-danger {
    background: #e53935;
    color: #fff;
}

.btn-sm {
    font-size: 0.85rem;
    padding: 0.3rem 0.8rem;
}

.btn-link {
    background: none;
    border: none;
    color: #1976d2;
    cursor: pointer;
    font-size: 0.9rem;
    text-decoration: underline;
}

.btn-submit {
    font-size: 1.1rem;
    padding: 0.75rem 2rem;
}

/* Error */
.error-message {
    background: #ffebee;
    border: 1px solid #ef9a9a;
    color: #c62828;
    padding: 0.5rem 0.75rem;
    border-radius: 4px;
    margin-top: 0.75rem;
}

/* Character count */
.char-count {
    text-align: right;
    font-size: 0.85rem;
    color: #666;
    margin-top: 0.25rem;
}

.char-count.over-limit {
    color: #c62828;
    font-weight: 600;
}

/* Work Entry / Reference fieldsets */
.work-entry-form,
.reference-form {
    border: 1px solid #e0e0e0;
    border-radius: 6px;
    padding: 1rem;
    margin-bottom: 1rem;
}

.work-entry-form legend,
.reference-form legend {
    font-weight: 600;
    padding: 0 0.5rem;
}

/* Review Step */
.review-section {
    border-bottom: 1px solid #eee;
    padding-bottom: 1rem;
    margin-bottom: 1rem;
}

.review-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.review-header h3 {
    margin: 0 0 0.5rem;
}

.review-section dl {
    display: grid;
    grid-template-columns: auto 1fr;
    gap: 0.25rem 1rem;
    margin: 0;
}

.review-section dt {
    font-weight: 500;
    color: #555;
}

.review-item {
    margin-bottom: 0.75rem;
}

.date-range {
    font-size: 0.9rem;
    color: #666;
}

.cover-letter-preview {
    white-space: pre-wrap;
    background: #fafafa;
    padding: 0.75rem;
    border-radius: 4px;
    border: 1px solid #eee;
}

/* Confirmation */
.confirmation {
    text-align: center;
    padding: 2rem;
}

.confirmation h3 {
    color: #4caf50;
    font-size: 1.5rem;
}

